    final provider = await _landEntry(
      registry,
      name: name,
      baseUrl: baseUrl,
      modelId: modelId,
    );
    registry.rememberKey(provider.id, credentials.authToken);
    _notify(provider);
    if (context.mounted) showFahSnack(context, 'CodeMie connected');
    return true;
  }

