    required this.registry,
    this.keychain,
    this.sessionKeys,
    this.onConnected,
    this.copilotCallbacks,
    this.codeMieSsoFn = desktopCodeMieSso,
    this.chatGptOAuthFn = desktopChatGptOAuth,
