  }) async {
    try {
      final ids = await fetchCodeMieModels(baseUrl, apiKey, client: client);
      return (ids, const <String, int>{}, const <String, int>{});
    } on Object {
      return (const <String>[], const <String, int>{}, const <String, int>{});
    }
  }
}

