String _uniqueEntryName(ProviderRegistry registry, String identity) {
  var name = identity;
  var suffix = 2;
  while (registry.providers.any(
    (p) => p.name == name && p.baseUrl == chatGptCodexBaseUrl,
  )) {
    name = '$identity-${suffix++}';
  }
  return name;
}

