import 'dart:convert';

import 'package:flutter/foundation.dart';
import 'package:flutter_agent_harness/flutter_agent_harness.dart';

import 'package:fa_ui/src/stores/keychain_store.dart';
import 'package:fa_ui/src/stores/session_keys_store.dart';

/// Provenance of a registry entry (issue #327 AC4): [localProviderProvenance]
/// for entries added on this surface (panel edit, preset connect, SSO flow);
/// anything else is a synced seed (`synced-from-cli@<host>` — the
/// extension's faProviders wording). The providers panel renders the matching
/// `[local]`/`[synced]` badge so a partition holding only synced (or only
/// local) rows is visible, not silent.
const localProviderProvenance = 'local';

/// A user-added OpenAI-compatible provider definition.
///
/// Definitions are non-secret (name, endpoint, default model) and are
/// persisted by [ProviderRegistry]; the API key is NOT part of the
/// definition — keys live in memory for the session only (see
/// [ProviderRegistry.rememberKey]).
final class CustomProvider {
  const CustomProvider({
    required this.id,
    required this.name,
    required this.baseUrl,
    required this.modelId,
    this.requiresKey = false,
    this.provenance = localProviderProvenance,
    this.kind,
  });

  /// Restores a definition from its JSON form (see [toJson]). Entries
  /// persisted before provenance existed read as [localProviderProvenance].
  factory CustomProvider.fromJson(Map<String, dynamic> json) => CustomProvider(
    id: json['id'] as String,
    name: json['name'] as String,
    baseUrl: json['baseUrl'] as String,
    modelId: json['modelId'] as String,
    requiresKey: json['requiresKey'] == true,
    provenance: (json['provenance'] as String?) ?? localProviderProvenance,
    kind: json['kind'] as String?,
  );

  /// Stable unique id (assigned by the registry at add time).
  final String id;

  /// Display name shown in the provider picker.
  final String name;

  /// OpenAI-compatible chat-completions endpoint.
  final String baseUrl;

  /// Default model id, prefilled when the provider is selected.
  final String modelId;

  /// Whether a key was ever remembered for this entry (issue #329): the
  /// non-secret marker letting the keyless-request guard tell "keyless by
  /// design" (Ollama/llama.cpp, never had a key) from "keyed entry whose
  /// key does not resolve on this surface" (secure store lost/broken) —
  /// the latter must fail with a named message, never a raw provider 401.
  final bool requiresKey;

  /// Where this entry came from: [localProviderProvenance] or a synced
  /// seed (`synced-from-cli@<host>`). Drives the panel's provenance badge.
  final String provenance;

  /// The entry's provider identity, saved by the connect flow that created
  /// it (`chatgpt-codex`, `copilot`, `dial`) — the model-list dispatch's
  /// identity hint beats URL-shape matching, so a codex entry whose URL was
  /// later edited/proxied stays on the codex wire. Null for plain
  /// OpenAI-shaped entries (URL matching is the only signal there).
  final String? kind;

  /// JSON form persisted in the registry file.
  Map<String, dynamic> toJson() => {
    'id': id,
    'name': name,
    'baseUrl': baseUrl,
    'modelId': modelId,
    if (requiresKey) 'requiresKey': true,
    'provenance': provenance,
    if (kind != null) 'kind': kind,
  };

  /// Identity is the [id], so edited copies match dropdown selections made
  /// from earlier instances.
  @override
  bool operator ==(Object other) => other is CustomProvider && other.id == id;

  @override
  int get hashCode => id.hashCode;

  @override
  String toString() => 'CustomProvider($id, $name)';
}

/// The user-added providers shown alongside the built-in presets in the
/// settings form's provider picker.
///
/// Definitions persist as JSON at `providers.json` in the root of the
/// sandbox filesystem ([ExecutionEnv.cwd]) — on web that file rides the
/// IndexedDB snapshot of the persistent env, on IO it is a plain file in the
/// sandbox/app-documents directory; the env abstraction makes both the same
/// code path. API keys are never persisted: [rememberKey] keeps them in
/// process memory for the session, so a reload requires re-entry (matching
/// the app's existing key policy).
class ProviderRegistry extends ChangeNotifier {
  ProviderRegistry._(this._env, [this._keychain, this._sessionKeysStore]);

  /// A registry without persistence (tests, widget fallbacks): mutations
  /// notify listeners but nothing is written anywhere.
