String chatgptEntryKeyName(String entryName) {
  const host = 'CHATGPT_COM'; // chatgpt.com, from chatGptCodexBaseUrl
  final sanitized = entryName
      .toUpperCase()
      .replaceAll(RegExp(r'[^A-Z0-9]+'), '_')
