  /// memory otherwise).
  static Future<ProviderRegistry> load(
    ExecutionEnv env, {
    KeychainStore? keychain,
    SessionKeysStore? sessionKeys,
  }) async {
    final registry = ProviderRegistry._(env, keychain, sessionKeys);
    await registry._load();
    return registry;
  }

