Future<bool> openBrowser(String url) async {
  String executable;
  List<String> args;
  if (Platform.isMacOS) {
    executable = 'open';
    args = [url];
  } else if (Platform.isLinux) {
    executable = 'xdg-open';
    args = [url];
  } else if (Platform.isWindows) {
    executable = 'start';
    args = ['', url];
  } else {
    return false;
  }
  try {
    final result = await Process.run(executable, args);
    return result.exitCode == 0;
  } on Object {
    return false;
  }
}

