  ) {
    final enabled = _hasSsoFlow(preset);
    final tile = ListTile(
      leading: ProviderMark(preset.key, size: 32),
      title: Text(preset.name),
      subtitle: Text(preset.description),
      enabled: enabled,
      trailing: Icon(
        Icons.chevron_right,
        size: 18,
        color: theme.colorScheme.onSurfaceVariant,
      ),
