    // never silent).
    final visiblePresets = <AddProviderPreset>[];
    final catalogHidden = <AddProviderPreset>[];
    for (final preset in presets) {
      if (!addProviderPresetEnabled(preset)) {
        catalogHidden.add(preset);
      } else {
