    this.onCodeMieSso,
    this.onChatGptOAuth,
    this.onCopilotConnect,
    this.openRouterOAuthCallbackUrl,
    this.openRouterOAuthCapture,
    this.sso,
    this.onDeviceRoutes = const [],
