                title: Text(route.label),
                subtitle: const Text('Runs on this device — download once'),
                trailing: Icon(
                  Icons.chevron_right,
                  size: 18,
                  color: theme.colorScheme.onSurfaceVariant,
                ),
                onTap: () => _onOnDeviceTap(context, route),
              ),
          ],
        ),
      ),
    );
  }

